from math import log2

def surprise(p):                 # 놀람 = log2(1/p)
    return log2(1 / p)

def entropy(counts):             # 색깔별 닭 수 → 엔트로피
    n = sum(counts)
    return sum((c / n) * surprise(c / n) for c in counts if c > 0)

areas = {"A": [6, 1], "B": [1, 10], "C": [7, 7]}
for name, cnt in areas.items():
    print(name, cnt, round(entropy(cnt), 2))

for orange in range(0, 15, 2):   # 14마리 중 주황이 늘어날 때
    print(orange, 14 - orange, round(entropy([orange, 14 - orange]), 2))
